insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001561', 'colleague', '/ˈkɒliːɡ/', 'noun', 'colega de trabalho', 'My colleague, who joined last year, is very skilled.', 'Meu colega, que entrou no ano passado, é muito habilidoso.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001562', 'neighbor', '/ˈneɪbər/', 'noun', 'vizinho', 'My neighbor, whose dog barks all night, apologized.', 'Meu vizinho, cujo cachorro late a noite toda, se desculpou.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001563', 'acquaintance', '/əˈkweɪntəns/', 'noun', 'conhecido', 'He is just an acquaintance, not a close friend.', 'Ele é apenas um conhecido, não um amigo próximo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001564', 'relative', '/ˈrelətɪv/', 'noun', 'parente', 'My aunt, who is a relative on my mother''s side, visited us.', 'Minha tia, que é parente do lado da minha mãe, nos visitou.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001565', 'mentor', '/ˈmentɔːr/', 'noun', 'mentor', 'My mentor, to whom I owe a lot, retired last year.', 'Meu mentor, a quem devo muito, se aposentou no ano passado.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001566', 'stranger', '/ˈstreɪndʒər/', 'noun', 'estranho, desconhecido', 'A stranger, whose name I never learned, helped me.', 'Um estranho, cujo nome eu nunca soube, me ajudou.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001567', 'landlord', '/ˈlændlɔːrd/', 'noun', 'proprietário (de imóvel)', 'The landlord, who lives upstairs, fixed the leak.', 'O proprietário, que mora no andar de cima, consertou o vazamento.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001568', 'tenant', '/ˈtenənt/', 'noun', 'inquilino', 'The tenant, whose lease ends in June, wants to renew it.', 'O inquilino, cujo contrato termina em junho, quer renová-lo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001569', 'author', '/ˈɔːθər/', 'noun', 'autor', 'The author, whose books I love, is visiting the city.', 'O autor, cujos livros eu amo, está visitando a cidade.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001570', 'character', '/ˈkærəktər/', 'noun', 'personagem', 'The character, who appears in every chapter, is my favorite.', 'O personagem, que aparece em todo capítulo, é meu favorito.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001571', 'background', '/ˈbækɡraʊnd/', 'noun', 'histórico, background', 'She has a background in engineering, which helps her a lot.', 'Ela tem um histórico em engenharia, o que a ajuda muito.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001572', 'reputation', '/ˌrepjuˈteɪʃən/', 'noun', 'reputação', 'The chef, whose reputation is excellent, opened a new restaurant.', 'O chef, cuja reputação é excelente, abriu um novo restaurante.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001573', 'characteristic', '/ˌkærəktəˈrɪstɪk/', 'noun', 'característica', 'Patience is a characteristic he values a lot.', 'Paciência é uma característica que ele valoriza muito.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001574', 'trait', '/treɪt/', 'noun', 'traço (de personalidade)', 'Kindness is a trait she inherited from her mother.', 'Bondade é um traço que ela herdou da mãe.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001575', 'biography', '/baɪˈɒɡrəfi/', 'noun', 'biografia', 'The biography, which took ten years to write, was a success.', 'A biografia, que levou dez anos para ser escrita, foi um sucesso.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001576', 'memoir', '/ˈmemwɑːr/', 'noun', 'memórias (livro)', 'Her memoir, which many people related to, became a bestseller.', 'As memórias dela, com as quais muitas pessoas se identificaram, viraram um best-seller.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001577', 'anecdote', '/ˈænɪkdoʊt/', 'noun', 'anedota', 'He told an anecdote that made everyone laugh.', 'Ele contou uma anedota que fez todo mundo rir.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001578', 'detail', '/ˈdiːteɪl/', 'noun', 'detalhe', 'The detail she mentioned changed the whole story.', 'O detalhe que ela mencionou mudou toda a história.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001579', 'aspect', '/ˈæspekt/', 'noun', 'aspecto', 'One aspect of his work I admire is his patience.', 'Um aspecto do trabalho dele que eu admiro é a paciência.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001580', 'feature', '/ˈfiːtʃər/', 'noun', 'característica, aspecto', 'A key feature of the app is its simple design.', 'Uma característica chave do aplicativo é o design simples.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001581', 'quality', '/ˈkwɒləti/', 'noun', 'qualidade', 'Honesty is a quality I value in a friend.', 'Honestidade é uma qualidade que eu valorizo em um amigo.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001582', 'category', '/ˈkætəɡəri/', 'noun', 'categoria', 'This book falls into the category of historical fiction.', 'Esse livro se encaixa na categoria de ficção histórica.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001583', 'definition', '/ˌdefɪˈnɪʃən/', 'noun', 'definição', 'The definition he gave was surprisingly simple.', 'A definição que ele deu foi surpreendentemente simples.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001584', 'context', '/ˈkɒntekst/', 'noun', 'contexto', 'Without context, the sentence is confusing.', 'Sem contexto, a frase fica confusa.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001585', 'reference', '/ˈrefərəns/', 'noun', 'referência', 'The teacher, to whom I asked for a reference, agreed happily.', 'O professor, a quem pedi uma referência, aceitou feliz.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001586', 'connection', '/kəˈnekʃən/', 'noun', 'conexão', 'There is a strong connection between the two stories.', 'Há uma forte conexão entre as duas histórias.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001587', 'relationship', '/rɪˈleɪʃənʃɪp/', 'noun', 'relacionamento', 'They have a relationship built on trust.', 'Eles têm um relacionamento construído sobre confiança.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001588', 'bond', '/bɒnd/', 'noun', 'vínculo', 'The two sisters share a special bond.', 'As duas irmãs compartilham um vínculo especial.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001589', 'describe', '/dɪˈskraɪb/', 'verb', 'descrever', 'It is hard to describe how she felt.', 'É difícil descrever como ela se sentiu.', 'B2', array['grammar']),
('30000000-0000-0000-0000-000000001590', 'define', '/dɪˈfaɪn/', 'verb', 'definir', 'Success is difficult to define.', 'Sucesso é difícil de definir.', 'B2', array['grammar']);

