('20000000-0000-0000-0000-000000000261', 'multiple_choice', 5, '{"question": "What does ''acquaintance'' mean?", "audio_text": null, "options": ["Conhecido", "Parente", "Mentor"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000261', 'matching', 6, '{"pairs": [{"left": "colleague", "right": "colega de trabalho"}, {"left": "neighbor", "right": "vizinho"}, {"left": "acquaintance", "right": "conhecido"}, {"left": "relative", "right": "parente"}, {"left": "mentor", "right": "mentor"}, {"left": "stranger", "right": "estranho"}]}'),
('20000000-0000-0000-0000-000000000261', 'fill_blank', 7, '{"sentence": "He is just an ___, not a close friend.", "options": ["acquaintance", "colleague", "mentor"], "correct": "acquaintance", "translation": "Ele é apenas um conhecido, não um amigo próximo."}'),
('20000000-0000-0000-0000-000000000261', 'fill_blank', 8, '{"sentence": "A ___, whose name I never learned, helped me.", "options": ["stranger", "relative", "neighbor"], "correct": "stranger", "translation": "Um estranho, cujo nome eu nunca soube, me ajudou."}'),
('20000000-0000-0000-0000-000000000261', 'word_order', 9, '{"words": ["My", "neighbor", "whose", "dog", "barks", "all", "night", "apologized"], "correct_sentence": "My neighbor whose dog barks all night apologized", "translation": "Meu vizinho, cujo cachorro late a noite toda, se desculpou"}'),
('20000000-0000-0000-0000-000000000261', 'word_order', 10, '{"words": ["My", "mentor", "to", "whom", "I", "owe", "a", "lot", "retired"], "correct_sentence": "My mentor to whom I owe a lot retired", "translation": "Meu mentor, a quem devo muito, se aposentou"}'),
('20000000-0000-0000-0000-000000000261', 'reading', 11, '{"passage": "In our lives, we interact with many kinds of people: a colleague we work with every day, a neighbor we see occasionally, an acquaintance we barely know, and a mentor whose advice we truly value. Sometimes even a stranger can leave a lasting impression.", "translation": "Em nossas vidas, interagimos com muitos tipos de pessoas: um colega com quem trabalhamos todos os dias, um vizinho que vemos ocasionalmente, um conhecido que mal conhecemos, e um mentor cujo conselho valorizamos de verdade. Às vezes até um estranho pode deixar uma impressão duradoura.", "question": "According to the text, what can even a stranger do?", "options": ["Become a mentor", "Leave a lasting impression", "Replace a colleague"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000261', 'listening', 12, '{"audio_text": "My colleague, who joined last year, is very skilled. My mentor, to whom I owe a lot, retired last year. A stranger helped me.", "question": "When did the mentor retire, according to the audio?", "options": ["Last year", "Last month", "It was not mentioned"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000261', 'dictation', 13, '{"audio_text": "He is just an acquaintance, not a close friend.", "expected": "He is just an acquaintance, not a close friend."}'),
('20000000-0000-0000-0000-000000000261', 'typing', 14, '{"prompt_pt": "Traduza usando oração relativa: ''Meu colega, que entrou ano passado, é muito habilidoso.''", "expected": "My colleague, who joined last year, is very skilled.", "ai_review": true}'),

-- Lição 262: Orações não-restritivas — introdução (landlord, tenant, author, character, background, reputation)
('20000000-0000-0000-0000-000000000262', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001567", "show_image": false}'),
('20000000-0000-0000-0000-000000000262', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001569", "show_image": false}'),
('20000000-0000-0000-0000-000000000262', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001571", "show_image": false}'),
('20000000-0000-0000-0000-000000000262', 'multiple_choice', 4, '{"question": "A non-defining relative clause is separated from the main sentence by:", "audio_text": null, "options": ["Commas", "Nothing at all", "Semicolons only"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000262', 'multiple_choice', 5, '{"question": "What does ''reputation'' mean?", "audio_text": null, "options": ["Reputação", "Personagem", "Inquilino"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000262', 'matching', 6, '{"pairs": [{"left": "landlord", "right": "proprietário"}, {"left": "tenant", "right": "inquilino"}, {"left": "author", "right": "autor"}, {"left": "character", "right": "personagem"}, {"left": "background", "right": "histórico"}, {"left": "reputation", "right": "reputação"}]}'),
('20000000-0000-0000-0000-000000000262', 'fill_blank', 7, '{"sentence": "The ___, who lives upstairs, fixed the leak.", "options": ["landlord", "tenant", "author"], "correct": "landlord", "translation": "O proprietário, que mora no andar de cima, consertou o vazamento."}'),
('20000000-0000-0000-0000-000000000262', 'fill_blank', 8, '{"sentence": "She has a ___ in engineering, which helps her a lot.", "options": ["background", "character", "reputation"], "correct": "background", "translation": "Ela tem um histórico em engenharia, o que a ajuda muito."}'),
('20000000-0000-0000-0000-000000000262', 'word_order', 9, '{"words": ["The", "chef", "whose", "reputation", "is", "excellent", "opened", "a", "restaurant"], "correct_sentence": "The chef whose reputation is excellent opened a restaurant", "translation": "O chef, cuja reputação é excelente, abriu um restaurante"}'),
('20000000-0000-0000-0000-000000000262', 'word_order', 10, '{"words": ["The", "character", "who", "appears", "in", "every", "chapter", "is", "my", "favorite"], "correct_sentence": "The character who appears in every chapter is my favorite", "translation": "O personagem, que aparece em todo capítulo, é meu favorito"}'),
('20000000-0000-0000-0000-000000000262', 'reading', 11, '{"passage": "Non-defining relative clauses add extra information that is not essential to identify the noun. For example: ''The landlord, who lives upstairs, fixed the leak.'' Here, we already know which landlord we mean, so the clause simply adds detail, and commas are always used.", "translation": "Orações relativas não-restritivas adicionam informação extra que não é essencial para identificar o substantivo. Por exemplo: ''The landlord, who lives upstairs, fixed the leak.''. Aqui, já sabemos qual proprietário estamos falando, então a oração apenas adiciona um detalhe, e vírgulas são sempre usadas.", "question": "What do non-defining relative clauses add, according to the text?", "options": ["Essential identification", "Extra, non-essential information", "A new subject"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000262', 'listening', 12, '{"audio_text": "The landlord, who lives upstairs, fixed the leak. The author, whose books I love, is visiting the city. The tenant wants to renew the lease.", "question": "Where does the landlord live, according to the audio?", "options": ["Downstairs", "Upstairs", "Next door"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000262', 'dictation', 13, '{"audio_text": "The landlord, who lives upstairs, fixed the leak.", "expected": "The landlord, who lives upstairs, fixed the leak."}'),
('20000000-0000-0000-0000-000000000262', 'typing', 14, '{"prompt_pt": "Traduza usando oração não-restritiva: ''O autor, cujos livros eu amo, está visitando a cidade.''", "expected": "The author, whose books I love, is visiting the city.", "ai_review": true}'),

-- Lição 263: Whom e whose (characteristic, trait, biography, memoir, anecdote, detail)
('20000000-0000-0000-0000-000000000263', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001573", "show_image": false}'),
('20000000-0000-0000-0000-000000000263', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001575", "show_image": false}'),
('20000000-0000-0000-0000-000000000263', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001577", "show_image": false}'),
('20000000-0000-0000-0000-000000000263', 'multiple_choice', 4, '{"question": "''Whom'' is used to replace:", "audio_text": null, "options": ["The object of a verb or preposition", "The subject of a clause", "A possessive noun"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000263', 'multiple_choice', 5, '{"question": "''Whose'' is used to show:", "audio_text": null, "options": ["Possession", "Location", "Time"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000263', 'matching', 6, '{"pairs": [{"left": "characteristic", "right": "característica"}, {"left": "trait", "right": "traço"}, {"left": "biography", "right": "biografia"}, {"left": "memoir", "right": "memórias"}, {"left": "anecdote", "right": "anedota"}, {"left": "detail", "right": "detalhe"}]}'),
('20000000-0000-0000-0000-000000000263', 'fill_blank', 7, '{"sentence": "Kindness is a ___ she inherited from her mother.", "options": ["trait", "detail", "memoir"], "correct": "trait", "translation": "Bondade é um traço que ela herdou da mãe."}'),
('20000000-0000-0000-0000-000000000263', 'fill_blank', 8, '{"sentence": "The ___ she mentioned changed the whole story.", "options": ["detail", "anecdote", "biography"], "correct": "detail", "translation": "O detalhe que ela mencionou mudou toda a história."}'),
('20000000-0000-0000-0000-000000000263', 'word_order', 9, '{"words": ["Patience", "is", "a", "characteristic", "he", "values", "a", "lot"], "correct_sentence": "Patience is a characteristic he values a lot", "translation": "Paciência é uma característica que ele valoriza muito"}'),
('20000000-0000-0000-0000-000000000263', 'word_order', 10, '{"words": ["He", "told", "an", "anecdote", "that", "made", "everyone", "laugh"], "correct_sentence": "He told an anecdote that made everyone laugh", "translation": "Ele contou uma anedota que fez todo mundo rir"}'),
('20000000-0000-0000-0000-000000000263', 'reading', 11, '{"passage": "''Whom'' is the formal object form of ''who'', used when the person is the object of a verb or preposition, as in ''the mentor to whom I owe a lot''. ''Whose'' shows possession, as in ''the neighbor whose dog barks all night''. Both are more common in formal writing, like a biography or a memoir.", "translation": "''Whom'' é a forma formal de objeto de ''who'', usada quando a pessoa é objeto de um verbo ou preposição, como em ''the mentor to whom I owe a lot''. ''Whose'' mostra posse, como em ''the neighbor whose dog barks all night''. Ambos são mais comuns na escrita formal, como uma biografia ou memórias.", "question": "What does ''whose'' show, according to the text?", "options": ["Time", "Possession", "Location"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000263', 'listening', 12, '{"audio_text": "Kindness is a trait she inherited from her mother. The biography took ten years to write. He told an anecdote that made everyone laugh.", "question": "How long did the biography take to write, according to the audio?", "options": ["Five years", "Ten years", "It was not mentioned"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000263', 'dictation', 13, '{"audio_text": "Kindness is a trait she inherited from her mother.", "expected": "Kindness is a trait she inherited from her mother."}'),
('20000000-0000-0000-0000-000000000263', 'typing', 14, '{"prompt_pt": "Traduza usando ''whom'': ''O mentor, a quem devo muito, se aposentou.''", "expected": "The mentor, to whom I owe a lot, retired.", "ai_review": true}'),

-- Lição 264: Preposição + pronome relativo (aspect, feature, quality, category, definition, context)
('20000000-0000-0000-0000-000000000264', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001579", "show_image": false}'),
('20000000-0000-0000-0000-000000000264', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001581", "show_image": false}'),
('20000000-0000-0000-0000-000000000264', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001583", "show_image": false}'),
('20000000-0000-0000-0000-000000000264', 'multiple_choice', 4, '{"question": "The book ___ which we talked is a bestseller.", "audio_text": null, "options": ["about", "who", "whose"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000264', 'multiple_choice', 5, '{"question": "What does ''feature'' mean here?", "audio_text": null, "options": ["Característica, aspecto", "Categoria", "Definição"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000264', 'matching', 6, '{"pairs": [{"left": "aspect", "right": "aspecto"}, {"left": "feature", "right": "característica"}, {"left": "quality", "right": "qualidade"}, {"left": "category", "right": "categoria"}, {"left": "definition", "right": "definição"}, {"left": "context", "right": "contexto"}]}'),
('20000000-0000-0000-0000-000000000264', 'fill_blank', 7, '{"sentence": "Without ___, the sentence is confusing.", "options": ["context", "quality", "feature"], "correct": "context", "translation": "Sem contexto, a frase fica confusa."}'),
('20000000-0000-0000-0000-000000000264', 'fill_blank', 8, '{"sentence": "This book falls into the ___ of historical fiction.", "options": ["category", "definition", "aspect"], "correct": "category", "translation": "Esse livro se encaixa na categoria de ficção histórica."}'),
('20000000-0000-0000-0000-000000000264', 'word_order', 9, '{"words": ["A", "key", "feature", "of", "the", "app", "is", "its", "simple", "design"], "correct_sentence": "A key feature of the app is its simple design", "translation": "Uma característica chave do aplicativo é o design simples"}'),
('20000000-0000-0000-0000-000000000264', 'word_order', 10, '{"words": ["Honesty", "is", "a", "quality", "I", "value", "in", "a", "friend"], "correct_sentence": "Honesty is a quality I value in a friend", "translation": "Honestidade é uma qualidade que eu valorizo em um amigo"}'),
('20000000-0000-0000-0000-000000000264', 'reading', 11, '{"passage": "In formal English, a preposition can go before the relative pronoun, as in ''the person to whom I spoke'' or ''the book about which we talked''. This is more common in writing, while in speech people usually say ''the person I spoke to'' or ''the book we talked about''.", "translation": "No inglês formal, uma preposição pode vir antes do pronome relativo, como em ''the person to whom I spoke'' ou ''the book about which we talked''. Isso é mais comum na escrita, enquanto na fala as pessoas geralmente dizem ''the person I spoke to'' ou ''the book we talked about''.", "question": "Where is ''preposition + relative pronoun'' more common, according to the text?", "options": ["In speech", "In writing", "It is never used"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000264', 'listening', 12, '{"audio_text": "Without context, the sentence is confusing. This book falls into the category of historical fiction. A key feature of the app is its simple design.", "question": "What is a key feature of the app, according to the audio?", "options": ["Its price", "Its simple design", "Its category"], "correct_index": 1}'),
